  const files='<div class="box"><h6>'+L('Documents','المستندات')+' · '+FILES.length+'</h6>'+FILES.map(f=>'<div class="fl"><span class="tic" style="background:var(--tone-'+f[1]+'-tint);color:var(--tone-'+f[1]+'-fg)"><i class="ti '+f[0]+'"></i></span><b>'+f[2]+'</b><small class="num">'+f[3]+'</small><button class="cb ter sm ic"><i class="ti ti-download"></i></button></div>').join('')+'</div>';
