  const p=P.find(x=>x.id===V.open);
  if(d.rm){p.items=p.items.filter(x=>x!==d.rm);p.log.push({a:'rm',by:ME,at:now(),t:d.rm});return flash(L(`${d.rm} removed — the submittal itself is unchanged`,`تمت إزالة ${d.rm} — التقديم نفسه لم يتغير`))}
  if(d.rmslot!=null){V.sub=null;const s=p.slots.splice(+d.rmslot,1)[0];p.log.push({a:'rmslot',by:ME,at:now(),t:s[0]});return Rr()}
  if(d.link!=null){V.add=true;V.addQ='';V.addSel=new Set();V.slotLink=+d.link;return Rr()}
  if(d.pick){if(V.slotLink!=null)V.addSel=new Set([d.pick]);else V.addSel.has(d.pick)?V.addSel.delete(d.pick):V.addSel.add(d.pick);return Rr()}
