  if(a==='clearf'){V.fsel={};V.q='';V.mine=false;FPop.close();return Rr()}
  if(a==='new'){V.newP={n:['',''],d:['',''],co:'tmc',to:'dcl',due:'Week 45',items:[],slots:[]};return Rr()}
  if(a==='add'){V.add=true;V.addQ='';V.addSel=new Set();V.slotLink=null;return Rr()}
